import math

def is_power(N, p):
    """Checks if N is a power of p (p^k, k >= 1)."""
    if N <= 0:
        return False

    # Since N must be p^k, we can repeatedly divide N by p
    if p == 1: return False # Should not happen given p is prime > 2

    while N > 1:
        if N % p != 0:
            return False
        N //= p
    return True

